class ModelNew(nn.Module):
    """
    A model that computes Triplet Margin Loss for metric learning tasks using a single fused CUDA kernel.
    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self.eps = 1e-6

    def forward(self, anchor, positive, negative):
        # Move inputs to CUDA and ensure dtype/contiguity
        orig_device = anchor.device
        # Ensure same device
        if not anchor.is_cuda or not positive.is_cuda or not negative.is_cuda:
